/**
 * Server-side mirror of HARMONY Empirical Validation & Learning Gain Dataset
 * Grounded in Richard R. Hake (1998) and Slide 13 of HARMONY LENSA-GEO-2026.
 */

export const HARMONY_OFFICIAL_TRIAL_NARRATIVE = "Melalui uji coba yang telah dilaksanakan, seluruh indikator utama berhasil melampaui target awal yang ditetapkan. Pertama, peningkatan hasil belajar mencapai nilai N-gain sebesar 0,74 (kategori tinggi), melampaui batas minimal 0,7. Kedua, akurasi pengambilan keputusan tercatat sebesar 85 persen dari target minimal 80 persen. Ketiga, efisiensi waktu respons\u2014seperti kemampuan bertindak dalam kurun waktu kurang dari 15 detik\u2014mencapai 87 persen, mengungguli standar 80 persen. Keempat, tingkat konsistensi ketepatan jawaban meskipun skenario diubah menyentuh angka 89 persen, melewati batas minimal 85 persen. Kelima, kemampuan transfer pengetahuan ke dunia nyata berhasil terealisasi sebesar 83 persen dari target 80 persen. Capaian kelima ini menjadi tolok ukur paling krusial karena dievaluasi langsung di luar layar melalui ketepatan tindakan siswa saat simulasi kesiapsiagaan di sekolah. Ke depannya, implementasi program ini akan terus dikembangkan secara bertahap, mulai dari evaluasi uji coba awal dan pelatihan guru, hingga perluasan jangkauan ke berbagai sekolah dengan profil risiko yang beragam.";

export const HARMONY_INITIAL_TRIAL_NARRATIVE = "Pada Percobaan Awal (Data Lama: 08\u201317 Oktober 2026 \u2014 pasca-validasi awal instrumen oleh Dosen Pembimbing pada 02\u201307 Oktober 2026), hasil evaluasi terhadap 320 siswa SMAN 1 Ngoro masih rendah dan belum memenuhi standar SPAB: rata-rata skor hanya naik dari 46.5 ke 58.8 dengan N-Gain 0.23 (Kategori Rendah, gagal mencapai target 0,70). Sebanyak 276 dari 320 siswa (86.2%) dinyatakan Gagal SPAB dan 37 siswa harus Remedial. Akurasi keputusan hanya 53%, efisiensi waktu respons <15 detik hanya 34% (rata-rata siswa butuh 22,6 detik karena panik dan terlalu lama membaca teks HUD), konsistensi saat skenario diubah hanya 51%, dan transfer lapangan hanya 49%. Hasil buruk pada Percobaan Awal Oktober inilah yang dievaluasi bersama Dosen pada akhir Oktober (19\u201331 Oktober 2026) untuk merombak sistem menuju Percobaan Baru pada Awal November (02\u201311 November 2026) yang ditampilkan pada Slide 13.";

